SELECT m.MASTER_DEPT_HIER_LEVEL_2_NAME, f.ORGANIZATION_NAME, COUNT(f.FCLT_ORGANIZATION_KEY) AS organization_count, MIN(f.ORGANIZATION_NUMBER) AS min_organization_number FROM MASTER_DEPT_HIERARCHY m JOIN FCLT_ORGANIZATION f ON m.DLC_KEY = f.DLC_KEY WHERE f.ASSIGNABLE = 1 AND f.ORGANIZATION_NAME != 'ADMISSIONS' AND f.ORGANIZATION_ID NOT IN ('138', '250') GROUP BY m.MASTER_DEPT_HIER_LEVEL_2_NAME, f.ORGANIZATION_NAME;